<?php require dirname(__DIR__).'/includes/bootstrap.php';require APP_ROOT.'/services/auth.php';if(!setting('external_auth')){unset($_SESSION['otp_challenge'],$_SESSION['otp_subject'],$_SESSION['otp_channel'],$_SESSION['oauth'],$_SESSION['oauth_next']);redirect(current_user()?'khach_hang/ho_so.php':'dang_nhap.php');}handle_form(function(){throttle('otp-check-ip',$_SERVER['REMOTE_ADDR']??'local',20,300);$id=$_SESSION['otp_challenge']??'';$r=check_otp($id,post('code'));$u=db_one("SELECT * FROM tai_khoan WHERE id=? AND trang_thai='HOAT_DONG'",[$r['tai_khoan_id']]);must((bool)$u,'Tài khoản không còn hoạt động.');if($r['muc_dich']==='LOGIN'){$sms=($_SESSION['otp_channel']??'')==='sms';must(($sms?$u['sdt_dang_nhap']:$u['email'])===($_SESSION['otp_subject']??'')&&($sms?$u['sdt_xac_minh_luc']:$u['email_xac_minh_luc']),'Thông tin đăng nhập đã đổi. Cần gửi mã mới.');must($u['quyen']!=='ADMIN','Quản trị cần đăng nhập bằng trang riêng.',403);auth_complete($u);}else{$me=require_role(['KHACH_HANG','NHAN_VIEN','ADMIN']);must((int)$me['id']===(int)$u['id'],'Thử thách không thuộc tài khoản.',403);if($r['muc_dich']==='VERIFY_EMAIL'){must($u['email']===($_SESSION['otp_subject']??''),'Email đã đổi, cần gửi mã mới.');execute('UPDATE tai_khoan SET email_xac_minh_luc=NOW() WHERE id=?',[$u['id']]);}else{must($u['so_dien_thoai']===($_SESSION['otp_subject']??''),'Số điện thoại đã đổi, cần gửi mã mới.');execute('UPDATE tai_khoan SET sdt_dang_nhap=so_dien_thoai,sdt_xac_minh_luc=NOW() WHERE id=?',[$u['id']]);}unset($_SESSION['otp_challenge']);flash('Đã xác minh thông tin liên hệ.');redirect('khach_hang/ho_so.php');}},'xac_thuc/kiem_tra_otp.php');page_start('Nhập mã xác thực');echo '<div class="auth panel">';token_form();field('code','Mã OTP','','text','required inputmode="numeric" autocomplete="one-time-code" maxlength="6"');echo '<button>Xác minh</button></form></div>';page_end();
